parameters.jsCode:
const j = $input.first().json || {};
const pass = Number(j.pass ?? j.passed ?? 0);
const fail = Number(j.fail ?? j.failed ?? 0);
const total = pass + fail;
const rate = total > 0 ? pass / total : 1;
return [{ json: { rate, total, driftScore: (rate < 0.7 && total > 0) ? 1 : 0 } }];
